import{_ as r,a0 as i,w as n,s as l,ao as I,I as o,x as e,a1 as a,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const g=JSON.parse('{"title":"準備好迎接 AIOps 時代 | LCTT x X-CMD","titleTemplate":false,"description":"準備好迎接 AIOps 時代 | LCTT (202209) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"準備好迎接 AIOps 時代 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"準備好迎接 AIOps 時代 | LCTT (202209) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202209/20220907 Get Ready to Embrace the AIOps Era","title":"準備好迎接 AIOps 時代","tag":"202209","desc":""},"relativePath":"202209/20220907 Get Ready to Embrace the AIOps Era.md","filePath":"[post].md"}'),d={name:"202209/20220907 Get Ready to Embrace the AIOps Era.md"};function m(A,t,T,O,u,h){const p=i("Link");return n(),l("div",null,[t[15]||(t[15]=I('<h1 id="準備好迎接-aiops-時代" tabindex="-1">準備好迎接 AIOps 時代 <a class="header-anchor" href="#準備好迎接-aiops-時代" aria-label="Permalink to “準備好迎接 AIOps 時代”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202209/23/083440mxyb6e388ze2sbbs.jpg" alt=""></p><blockquote><p>隨着技術的進步，企業，無論大小，都必須將自己轉變為數字公司。轉型不再是“選擇”的問題；相反，它是關於“如何”推進過渡。這就是 AIOps 的用武之地。</p></blockquote><p>將組織轉變為數字公司會遇到很多挑戰。缺乏專門的 IT 技能、組織變革管理、不斷變化的客户需求和混合環境只是其中的一小部分。企業需要增強其 IT 運營（ITOps）以應對這些挑戰並滿足客户期望。</p><h3 id="數字化轉型-aiops-之路" tabindex="-1">數字化轉型：AIOps 之路 <a class="header-anchor" href="#數字化轉型-aiops-之路" aria-label="Permalink to “數字化轉型：AIOps 之路”">​</a></h3><p>未來，ITOps 將結合算法和人工智能，使 IT 系統的性能變得透明，並幫助他們提供無縫體驗。</p><blockquote><p>“AIOps 對 IT 運營的長期影響將是變革性的。” —— Gartner</p></blockquote><p>AIOps 對於成功的數字化轉型至關重要，可以幫助系統以現代業務所需的速度運行。反過來，這將確定公司獲得和保持市場領先地位的速度。</p><p>現代 AIOps 技術在本地、雲端或混合環境中提供 IT 基礎架構。它們的自動化使開發人員能夠專注於設計下一代業務應用，而不必擔心底層基礎設施。</p><h3 id="什麼是-aiops" tabindex="-1">什麼是 AIOps？ <a class="header-anchor" href="#什麼是-aiops" aria-label="Permalink to “什麼是 AIOps？”">​</a></h3><p>AIOps 結合人工智能和機器學習來分析 IT 運營的數據。這是將人工智能應用於 IT 運營的過程。它可以幫助組織主動檢測錯誤，還可以幫助運營團隊在問題影響最終用户之前預防問題。</p><p>傳統的 IT 管理技術已經無法應對數字化業務轉型。當 Gartner 創造 AIOps 一詞時，該公司預測 IT 運營過程將發生重大變化，組織管理其 IT 生態系統的方式也會發生巨大變化。</p><p>AIOps 平台使用大數據。他們從各種 IT 運營和設備收集數據，以自動識別和實時響應問題，同時仍提供傳統的歷史分析。然後，AIOps 使用機器學習對組合的 IT 數據執行綜合分析。</p><p>結果是自動化驅動的洞察力驅使持續改進和修復。AIOps 支持基本 IT 功能的持續集成和部署 （CI/CD）。</p><h3 id="aiops-的範圍是什麼" tabindex="-1">AIOps 的範圍是什麼？ <a class="header-anchor" href="#aiops-的範圍是什麼" aria-label="Permalink to “AIOps 的範圍是什麼？”">​</a></h3><p>開始使用 AIOps 最初似乎具有挑戰性，因此最好採取循序漸進的方法。我們需要從識別和理解 IT 運營數據開始。 AIOps 的核心是數據驅動。因此，它需要訪問所有相關的操作數據，包括非結構化數據、日誌、指標、實時數據、API 輸出和設備數據。還需要結構化的業務數據，例如資料庫、社交活動和其他關係數據。 AIOps 平台處理的相關數據越多，他們的預測就越準確。</p><p>企業需要了解他們的數據如何幫助他們解決最大的問題，無論他們身處哪個行業。他們應該實施 AIOps 來回顧他們過去的失敗，並確定哪些數據將幫助他們找到解決方案。</p><p>數據分析可用於查找中斷或系統變慢的根源。然後 AIOps 平台可用於檢測常見問題及其補救措施。企業可以使用收集到的結果來實施機器學習和 AI，以進行實時監控和自動響應。這整個過程幫助公司推動 AI 成熟，有效地修復錯誤，避免停機，提高效率。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/07/Figure-1-AIOps-platform-enabling-continuous-insight-across-IT-operations-monitoring-ITOM-2.jpg" alt="圖 1：AIOps 平台可實現對 IT 運營監控 (ITOM) 的持續洞察（來源：https://www.gartner.com/en/documents/3971186）"></p><h3 id="為什麼-2022-年需要-aiops" tabindex="-1">為什麼 2022 年需要 AIOps？ <a class="header-anchor" href="#為什麼-2022-年需要-aiops" aria-label="Permalink to “為什麼 2022 年需要 AIOps？”">​</a></h3><p>隨着企業加快數字化轉型，應用程序和系統架構變得非常先進。我們可以通過以下幾種方式見證這種複雜性：</p><ul><li>組織正在從傳統的應用架構轉移到雲原生、靈活和基於微服務的容器化應用堆棧。</li><li>這些應用也部署在本地、混合、公共和私有云平台上。</li></ul><p>隨着應用和 IT 環境的擴展，它們會產生大量數據。 IT 運營團隊因無法管理的數據而筋疲力盡。但是，人工智能可以處理大量數據。隨着數據量的擴大，將人工智能納入 IT 流程的機會要大得多。</p><p>異常檢測、分類和預測都可以通過使用機器學習和深度學習模型來完成，這些模型擅長分析海量數據並提供分析。AIOps 的許多功能可幫助公司通過交互式儀表盤提供良好的用户體驗。</p><p>實施 AIOps 的企業報告了諸如無縫體驗、更低的運營費用、更快的客户服務、更短的平均解決時間和更少的停機時間等好處。 AIOps 通過基於預測分析做出堅定的決策來支持 IT 運營。</p><h3 id="最後一點" tabindex="-1">最後一點 <a class="header-anchor" href="#最後一點" aria-label="Permalink to “最後一點”">​</a></h3><p>AIOps 是 IT 運營分析（ITOA）的下一步。 人工智能、認知技能和 RPA（機器人流程自動化）用於在基礎設施或 IT 運營問題成為問題之前自動修復它們。 自我修復系統是 AIOps 的最終目標。</p><hr>',28)),o("p",null,[t[1]||(t[1]=e("via: ",-1)),a(p,{href:"https://www.opensourceforu.com/2022/09/get-ready-to-embrace-the-aiops-era/"},{default:s(()=>[...t[0]||(t[0]=[e("https://www.opensourceforu.com/2022/09/get-ready-to-embrace-the-aiops-era/",-1)])]),_:1})]),o("p",null,[t[6]||(t[6]=e("作者：",-1)),a(p,{href:"https://www.opensourceforu.com/author/amit-shingala/"},{default:s(()=>[...t[2]||(t[2]=[e("Amit Shingala",-1)])]),_:1}),t[7]||(t[7]=e(" 選題：",-1)),a(p,{href:"https://github.com/lkxed"},{default:s(()=>[...t[3]||(t[3]=[e("lkxed",-1)])]),_:1}),t[8]||(t[8]=e(" 譯者：",-1)),a(p,{href:"https://github.com/geekpi"},{default:s(()=>[...t[4]||(t[4]=[e("geekpi",-1)])]),_:1}),t[9]||(t[9]=e(" 校對：",-1)),a(p,{href:"https://github.com/wxy"},{default:s(()=>[...t[5]||(t[5]=[e("wxy",-1)])]),_:1})]),o("p",null,[t[12]||(t[12]=e("本文由 ",-1)),a(p,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[10]||(t[10]=[e("LCTT",-1)])]),_:1}),t[13]||(t[13]=e(" 原創編譯，",-1)),a(p,{href:"https://linux.cn/"},{default:s(()=>[...t[11]||(t[11]=[e("Linux中國",-1)])]),_:1}),t[14]||(t[14]=e(" 榮譽推出",-1))])])}const x=r(d,[["render",m]]);export{g as __pageData,x as default};
